import { createTheme, responsiveFontSizes } from '@mui/material';
import { cyan, pink } from '@mui/material/colors';

const theme = responsiveFontSizes(
  createTheme({
    palette: {
      mode: 'light',
      primary: cyan,
      secondary: pink,
      error: {
        main: '#ff6358',
      },
      background: {
        default: '#ffffff',
        paper: '#ffffff',
      },
    },
    breakpoints: {
      values: {
        xs: 0,
        sm: 600,
        md: 960,
        lg: 1280,
        xl: 1920,
      },
    },
    components: {
      MuiCssBaseline: {
        styleOverrides: `
          html {
            scroll-behavior: smooth;
          }
        `,
      },
    },
  })
);

export default theme;